mkdir -p sample-app/.github/workflows sample-app/.githooks && cd sample-app && git init && git config user.name 'Demo User' && git config user.email 'demo@example.com' && printf '# Sample App

Tiny demo repo for Git workflow optimization.
' > README.md && printf '{
  "name": "sample-app",
  "version": "1.0.0",
  "private": true,
  "scripts": {
    "lint": "node scripts/lint.js",
    "test": "node scripts/test.js",
    "validate": "npm run lint && npm test"
  }
}
' > package.json && mkdir -p scripts src && printf "const fs = require('fs');
const text = fs.readFileSync('src/index.js', 'utf8');
if (!text.includes('module.exports')) {
  console.error('lint failed: src/index.js must export a module');
  process.exit(1);
}
console.log('lint ok');
" > scripts/lint.js && printf "const mod = require('../src/index');
if (mod.sum(2, 3) !== 5) {
  console.error('test failed');
  process.exit(1);
}
console.log('tests ok');
" > scripts/test.js && printf "function sum(a, b) {
  return a + b;
}

module.exports = { sum };
" > src/index.js && git add . && git commit -m 'chore: initial commit'

